-- POI: koordinat nyata, radius, konten
update public.poi set name = 'Pintu Utama Kiara Artha Park', short_name = 'Pintu Utama', category_id = 'akses', zone = 'Gerbang barat, sisi Jl. Banten', location = extensions.st_setsrid(extensions.st_makepoint(107.6407033, -6.9161917), 4326)::extensions.geography, radius_m = 25, description = 'Pintu masuk utama Kiara Artha Park berada di sisi barat, menghadap Jl. Banten. Dari sini jalur pejalan kaki mengarah ke lingkar Jl. Kiara Artha yang mengelilingi danau dan air mancur menari di tengah taman. Zona taman tersusun melingkar: area kuliner dan kafe di sisi selatan, danau dan air mancur di tengah, area bermain anak di sisi timur, serta jalur jogging dan musala di sisi utara.', trigger_response = 'Audio sambutan, ringkasan zona taman, dan rekomendasi rute sesuai jam kunjungan.', qr_code = 'SETARA:POI:P01', data_source = 'google_maps', is_published = true, summary = 'Gerbang utama di sisi Jl. Banten, titik awal menjelajah taman.', narration = 'Wilujeng sumping di Kiara Artha Park! Aku Kia, teman jelajahmu. Kamu sekarang di gerbang barat, sisi Jalan Banten. Taman ini diresmikan tanggal tujuh belas Agustus dua ribu sembilan belas, dan sekarang jadi salah satu ruang publik favorit warga Bandung. Tata letaknya melingkar, lho. Di tengah ada danau dengan air mancur menari. Di sisi utara ada titik start jogging track dan musala. Area bermain anak di sisi timur, dan area kuliner di sisi selatan. Ikuti jalur pejalan kaki ke timur untuk sampai di lingkar taman. Nanti aku sapa lagi setiap kamu dekat spot seru. Oh iya, di tiap spot ada kuis dan misi kecil. Kumpulkan bintangnya, ya!', activities = array['Peta ringkas zona taman', 'Titik kumpul rombongan', 'Akses ke Selter BOSEH dan area parkir']::text[], tips = array['Foto papan peta di gerbang sebagai cadangan bila baterai menipis.', 'Sore hari (15.00–18.00) cocok untuk jalan santai sebelum pertunjukan air mancur.']::text[], best_times = array['pagi', 'siang', 'sore', 'malam']::text[], keywords = array['gerbang', 'pintu', 'masuk', 'jl banten', 'peta', 'tiket']::text[], art = 'gate', status_note = null, source_place = 'Google Maps: "Gerbang Barat Taman Kiara Artha"', sort_order = 1 where id = 'P01';
update public.poi set name = 'Gerbang Area Parkir', short_name = 'Area Parkir', category_id = 'akses', zone = 'Area parkir sisi barat laut, dekat gerbang utama', location = extensions.st_setsrid(extensions.st_makepoint(107.6411222, -6.9154692), 4326)::extensions.geography, radius_m = 25, description = 'Area parkir utama berada di sisi barat laut taman, tidak jauh dari Jl. Banten. Dari gerbang parkir, pengunjung dapat berjalan ke selatan menuju Pintu Utama, atau ke timur menuju titik start jogging track, musala, dan toilet di sisi utara taman. Selter Sepeda BOSEH juga berada di dekat sini.', trigger_response = 'Notifikasi selamat datang, arah ke pintu utama, dan info fasilitas terdekat.', qr_code = 'SETARA:POI:P02', data_source = 'google_maps', is_published = true, summary = 'Area parkir utama; arah ke Pintu Utama dan fasilitas terdekat.', narration = 'Halo, selamat datang! Kamu ada di gerbang area parkir, sisi barat laut taman. Mau ke Pintu Utama? Jalan saja sekitar sembilan puluh meter ke selatan. Kalau mau langsung olahraga, titik start jogging track ada di sebelah timur, dekat musala dan toilet. Selter sepeda BOSEH juga dekat dari sini. Sebelum jalan, ingat-ingat dulu lokasi kendaraanmu, ya. Itu misi pertamamu di sini!', activities = array['Parkir mobil dan motor', 'Arah ke Pintu Utama (±90 m ke selatan)', 'Toilet terdekat di sisi utara taman']::text[], tips = array['Catat blok parkir kendaraan Anda.', 'Akhir pekan sore hari biasanya ramai; datang sebelum pukul 16.00.']::text[], best_times = array['pagi', 'siang', 'sore', 'malam']::text[], keywords = array['parkir', 'mobil', 'motor', 'kendaraan', 'gerbang']::text[], art = 'parking', status_note = null, source_place = 'Google Maps: "Kiara Artha Parking Lot"', sort_order = 2 where id = 'P02';
update public.poi set name = 'Danau & Air Mancur Menari', short_name = 'Air Mancur', category_id = 'atraksi', zone = 'Danau buatan di area tengah taman', location = extensions.st_setsrid(extensions.st_makepoint(107.6422657, -6.9160874), 4326)::extensions.geography, radius_m = 40, description = 'Danau di jantung taman ini adalah ikon Kiara Artha Park. Pada malam hari, air mancur menari tampil dengan permainan cahaya dan musik. Siang hingga sore, tepian danau menjadi tempat favorit untuk duduk santai, menikmati angin, dan memandangi patung Friendship Shake Hand di tepi utara.', trigger_response = 'Kartu informasi dan narasi; sore/malam menampilkan hitung mundur pertunjukan air mancur.', qr_code = 'SETARA:POI:P03', data_source = 'google_maps', is_published = true, summary = 'Ikon taman: danau dengan pertunjukan air mancur menari di malam hari.', narration = 'Kamu sampai di tepi danau, jantung Kiara Artha Park! Di tengah danau inilah air mancur menari tampil setiap malam. Pertunjukannya biasanya mulai jam setengah tujuh malam sampai setengah sembilan, dengan tema berbeda tiap jam. Semburan airnya bergerak mengikuti musik dan disinari lampu warna-warni. Coba lihat ke tepi utara danau. Ada patung dua tangan yang berjabat, namanya Friendship Shake Hand, simbol persahabatan. Kalau kamu datang siang, nikmati angin di tepi danau dulu, lalu balik lagi saat matahari terbenam. Bisa temukan patungnya? Itu misimu!', activities = array['Menonton pertunjukan air mancur menari (malam)', 'Duduk santai di tepi danau', 'Foto dengan latar air mancur']::text[], tips = array['Datang 15 menit sebelum pertunjukan untuk mendapat posisi depan.', 'Akses menonton disebut termasuk dalam paket Kiara Pelangi Food Court Rp35.000 (Orami, 2024); konfirmasi di lokasi.']::text[], best_times = array['sore', 'malam']::text[], keywords = array['danau', 'air mancur', 'fountain', 'pertunjukan', 'malam', 'lampu', 'show']::text[], art = 'fountain', status_note = 'Jadwal pertunjukan dapat berubah; cek Instagram @kiaraarthapark.', source_place = 'Google Maps: "Dancing Fountain"', sort_order = 3 where id = 'P03';
update public.poi set name = 'Area Tematik Asia', short_name = 'Tematik Asia', category_id = 'atraksi', zone = 'Zona bergaya Korea di sisi barat, dekat Jl. Banten', location = extensions.st_setsrid(extensions.st_makepoint(107.6406188, -6.9156793), 4326)::extensions.geography, radius_m = 30, description = 'Zona tematik bergaya Asia berada di sisi barat taman, dekat Jl. Banten. Area ini dikenal sebagai Kampung Korea: deretan bangunan dan ornamen bernuansa Korea yang sejak awal menjadi magnet foto pengunjung dan membuat Kiara Artha Park dijuluki destinasi "ala Korea" di tengah Kota Bandung.', trigger_response = 'Prompt suara, kartu informasi, dan stempel POI.', qr_code = 'SETARA:POI:P04', data_source = 'google_maps', is_published = true, summary = 'Zona tematik bernuansa Asia, dikenal sebagai Kampung Korea.', narration = 'Kamu ada di Area Tematik Asia, sisi barat taman. Kawasan ini dikenal sebagai Kampung Korea. Waktu taman dibuka tahun dua ribu sembilan belas, deretan bangunan dan ornamen bernuansa Korea di sini langsung jadi magnet foto, sampai Kiara Artha Park dijuluki destinasi ala Korea di tengah Bandung. Sekarang Google Maps mencatat area ini tutup, jadi kita amati dari luar saja, ya. Perhatikan atap, warna, dan tulisan Hangeul-nya. Setelah ini, lanjut ke Taman Asia Afrika di sisi selatan danau, spot foto paling ikonik di taman.', activities = array['Berfoto dengan ornamen bernuansa Asia', 'Mendengarkan cerita budaya lewat narasi audio']::text[], tips = array['Cahaya terbaik untuk foto: pagi 08.00–10.00 saat matahari dari timur.']::text[], best_times = array['pagi', 'siang', 'sore']::text[], keywords = array['asia', 'korea', 'kampung korea', 'budaya', 'tematik', 'foto']::text[], art = 'asia', status_note = 'Google Maps menandai "Kampung Korea Bandung" sebagai tutup permanen (diakses 16 Nov 2026). Konfirmasi kondisi area saat survei lapangan.', source_place = 'Google Maps: "KAMPUNG KOREA BANDUNG"', sort_order = 4 where id = 'P04';
update public.poi set name = 'Spot Foto Ikonik: Taman Asia Afrika', short_name = 'Taman Asia Afrika', category_id = 'atraksi', zone = 'Sisi selatan danau', location = extensions.st_setsrid(extensions.st_makepoint(107.6421607, -6.9166173), 4326)::extensions.geography, radius_m = 25, description = 'Taman Asia Afrika di sisi selatan danau adalah spot foto paling ikonik di Kiara Artha Park, dengan latar danau dan air mancur menari. Namanya menggemakan Konferensi Asia Afrika 1955 yang membuat Bandung dikenal dunia.', trigger_response = 'Cerita singkat spot serta tips waktu dan sudut foto terbaik.', qr_code = 'SETARA:POI:P05', data_source = 'google_maps', is_published = true, summary = 'Spot foto utama dengan latar danau dan air mancur.', narration = 'Wilujeng sumping di Taman Asia Afrika, spot foto paling ikonik di Kiara Artha Park! Namanya mengingatkan kita pada Konferensi Asia Afrika tahun seribu sembilan ratus lima puluh lima, waktu pemimpin dua puluh sembilan negara berkumpul di Gedung Merdeka, Bandung. Dari sini, danau dan air mancur menari kelihatan utuh. Untuk foto terbaik, menghadaplah ke utara. Pagi hari cahayanya lembut dari samping, malam hari air mancurnya warna-warni. Siapkan gaya terbaikmu, lalu simpan fotonya di Jurnal Kunjungan!', activities = array['Foto dengan latar danau dan air mancur', 'Foto rombongan']::text[], tips = array['Sudut terbaik: menghadap utara ke arah air mancur.', 'Foto malam: aktifkan mode malam dan tunggu pertunjukan air mancur dimulai.']::text[], best_times = array['pagi', 'sore', 'malam']::text[], keywords = array['foto', 'ikonik', 'asia afrika', 'spot foto', 'instagram', 'selfie']::text[], art = 'photo', status_note = null, source_place = 'Google Maps: "Taman Asia Afrika - Kiara Artha Park"', sort_order = 5 where id = 'P05';
update public.poi set name = 'Titik Start Jogging Track', short_name = 'Start Jogging', category_id = 'wellness', zone = 'Awal jalur jogging, sisi utara taman', location = extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, radius_m = 25, description = 'Titik awal jalur jogging berada di sisi utara taman. Jalur ini mengikuti lingkar Jl. Kiara Artha yang mengelilingi danau, sekitar 750 meter per putaran, cocok untuk jalan cepat, jogging, maupun bersepeda santai.', trigger_response = 'Tawaran memulai Wellness Trail, info panjang rute, dan tips pemanasan.', qr_code = 'SETARA:POI:P06', data_source = 'google_maps', is_published = true, summary = 'Awal jalur jogging lingkar taman; mulai Wellness Trail dari sini.', narration = 'Kamu di titik start jogging track! Jalur di depanmu mengikuti lingkar Jalan Kiara Artha yang mengelilingi danau, kira-kira tujuh ratus lima puluh meter satu putaran. Sebelum mulai, yuk pemanasan tiga sampai lima menit: putar pergelangan kaki, ayunkan lengan, lalu jalan di tempat. Mau dipandu? Mulai Wellness Trail dari menu Trail, nanti aku temani di setiap checkpoint dan catat jarak serta durasimu. Ayo, pemanasan bareng aku dulu!', activities = array['Memulai Wellness Trail', 'Jogging lingkar taman (±750 m per putaran)', 'Pemanasan sebelum berlari']::text[], tips = array['Lakukan pemanasan 3–5 menit sebelum berlari.', 'Pagi pukul 06.00–09.00 udara paling segar dan jalur belum ramai.']::text[], best_times = array['pagi', 'sore']::text[], keywords = array['jogging', 'lari', 'olahraga', 'track', 'trail', 'jalan pagi', 'wellness']::text[], art = 'jogging', status_note = null, source_place = 'Google Maps: "Jogging Track Kiara Artha Park"', sort_order = 6 where id = 'P06';
update public.poi set name = 'Selter Sepeda BOSEH', short_name = 'Selter BOSEH', category_id = 'wellness', zone = 'Sisi barat taman, dekat area parkir', location = extensions.st_setsrid(extensions.st_makepoint(107.6408092, -6.915669), 4326)::extensions.geography, radius_m = 20, description = 'Selter Bike on the Street Everybody Happy (BOSEH) di sisi barat taman. Pengunjung dapat menyewa sepeda untuk berkeliling lingkar taman maupun menjelajah Bandung. Di dalam taman juga tersedia persewaan sepeda dan skuter listrik swasta.', trigger_response = 'Info cara sewa sepeda/skuter, tarif dan jam operasional, serta rute bersepeda.', qr_code = 'SETARA:POI:P07', data_source = 'google_maps', is_published = true, summary = 'Sewa sepeda BOSEH untuk berkeliling taman dan kota.', narration = 'Ini Selter Sepeda BOSEH, singkatan dari Bike on the Street Everybody Happy, program sepeda sewa Pemerintah Kota Bandung. Cara sewanya gampang: daftar pakai kartu identitas di petugas atau aplikasi BOSEH, lalu pilih sepeda yang tersedia. Tarif resminya mulai seribu rupiah untuk jam pertama. Di dalam taman juga ada sewa sepeda dan skuter listrik, sekitar tiga puluh sampai empat puluh ribu rupiah. Rute favorit: lingkar Jalan Kiara Artha mengelilingi danau. Tetap utamakan pejalan kaki, ya!', activities = array['Sewa sepeda BOSEH', 'Sewa sepeda/skuter listrik di dalam taman', 'Bersepeda di lingkar taman']::text[], tips = array['Siapkan kartu identitas untuk registrasi.', 'Gunakan jalur lingkar dan utamakan pejalan kaki.']::text[], best_times = array['pagi', 'sore']::text[], keywords = array['sepeda', 'boseh', 'skuter', 'sewa', 'bike', 'bersepeda']::text[], art = 'bike', status_note = 'Jam layanan mengacu pada jam booth BOSEH Pemkot Bandung; konfirmasi saat survei.', source_place = 'Google Maps: "Stasiun Boseh Kiara Artha Park"', sort_order = 7 where id = 'P07';
update public.poi set name = 'Area Kuliner / Food Court', short_name = 'Area Kuliner', category_id = 'kuliner', zone = 'Kawasan Kiara Pelangi, sisi selatan taman', location = extensions.st_setsrid(extensions.st_makepoint(107.641775, -6.9170555), 4326)::extensions.geography, radius_m = 30, description = 'Kawasan kuliner di sisi selatan taman dengan beragam tenant makanan dan minuman. Kiara Pelangi Food Court menjadi pusatnya, berdekatan dengan kafe seperti Ludo Sports Kitchen and Coffee dan Monday Co. Pilihan tepat untuk makan bersama sebelum menonton air mancur menari.', trigger_response = 'Info tenant dan jam buka; jika belum buka, tampilkan jam buka dan alternatif terdekat.', qr_code = 'SETARA:POI:P08', data_source = 'google_maps', is_published = true, summary = 'Kiara Pelangi Food Court dan deretan kafe di sisi selatan.', narration = 'Kamu tiba di Area Kuliner! Di kawasan Kiara Pelangi ini ada food court dengan banyak tenant, dari makanan berat sampai jajanan dan minuman segar. Di sekitarnya ada kafe populer seperti Ludo Sports Kitchen and Coffee dan Monday Co. Menariknya, paket Kiara Pelangi Food Court disebut sudah termasuk akses menonton air mancur menari, jadi kamu bisa makan malam sambil menunggu pertunjukan. Jam buka tiap tenant beda-beda, cek papan info di lokasi, ya. Selamat makan, dan jangan lupa foto menu favoritmu!', activities = array['Makan dan minum di food court', 'Nongkrong di kafe sekitar', 'Membeli paket makan + akses air mancur']::text[], tips = array['Jam makan malam akhir pekan ramai; pesan lebih awal sebelum pertunjukan air mancur.', 'Jam buka tenant bervariasi.']::text[], best_times = array['siang', 'sore', 'malam']::text[], keywords = array['makan', 'kuliner', 'food court', 'kiara pelangi', 'restoran', 'minum', 'jajan']::text[], art = 'food', status_note = 'Jam buka tenant bervariasi; konfirmasi saat survei.', source_place = 'Google Maps: "Pelangi Graha Park"', sort_order = 8 where id = 'P08';
update public.poi set name = 'Area Kafe & Lapangan Padel', short_name = 'Kafe & Padel', category_id = 'kuliner', zone = 'Kawasan kafe dan lapangan padel, sisi utara', location = extensions.st_setsrid(extensions.st_makepoint(107.6422184, -6.9149564), 4326)::extensions.geography, radius_m = 30, description = 'Kawasan kafe dan lapangan padel di sisi utara taman. Padel, olahraga raket perpaduan tenis dan squash, sedang populer di Bandung, dan Padel Co. menyediakan lapangan semi-outdoor di sini. Kafe di sekitarnya cocok untuk beristirahat setelah berolahraga.', trigger_response = 'Info kafe, lapangan padel, jam operasional, dan aktivitas yang tersedia.', qr_code = 'SETARA:POI:P09', data_source = 'google_maps', is_published = true, summary = 'Kafe dan lapangan padel semi-outdoor di sisi utara taman.', narration = 'Kamu ada di Area Kafe dan Lapangan Padel, sisi utara taman. Tahu nggak, padel lahir di Meksiko tahun seribu sembilan ratus enam puluh sembilan? Mainnya mirip tenis, tapi lapangannya lebih kecil, dikelilingi dinding kaca, dan bolanya boleh memantul ke dinding. Lapangan semi-outdoor di sini bisa dipesan langsung ke pengelola. Kalau cuma mau santai, kafe di sekitarnya pas untuk minum sambil nonton pertandingan. Coba tonton satu reli sampai selesai, deh!', activities = array['Menonton atau bermain padel', 'Bersantai di kafe', 'Istirahat setelah jogging']::text[], tips = array['Pemesanan lapangan dilakukan langsung ke pengelola; SETARA tidak menyediakan reservasi.', 'Gunakan sepatu bersol rata untuk bermain padel.']::text[], best_times = array['pagi', 'sore', 'malam']::text[], keywords = array['padel', 'kafe', 'cafe', 'kopi', 'olahraga', 'raket', 'nongkrong']::text[], art = 'padel', status_note = 'Jam operasional perlu dikonfirmasi ke pengelola saat survei.', source_place = 'Google Maps: "Padel Co. Semi Outdoor"', sort_order = 9 where id = 'P09';
update public.poi set name = 'Area Bermain Anak', short_name = 'Area Bermain', category_id = 'keluarga', zone = 'Lollipop Playland, sisi timur danau', location = extensions.st_setsrid(extensions.st_makepoint(107.6428604, -6.9164994), 4326)::extensions.geography, radius_m = 25, description = 'Lollipop Playland adalah area bermain anak di sisi timur danau, lengkap dengan kafe bagi orang tua dan pendamping. Lokasinya dekat Zona Relaksasi, sehingga pendamping bisa beristirahat di tempat teduh setelah anak-anak bermain.', trigger_response = 'Info wahana, batas usia, tips keamanan anak, dan fasilitas terdekat bagi pendamping.', qr_code = 'SETARA:POI:P10', data_source = 'google_maps', is_published = true, summary = 'Lollipop Playland: wahana bermain anak dan kafe untuk pendamping.', narration = 'Halo keluarga! Kamu di dekat Lollipop Playland, area bermain anak di sisi timur danau. Anak-anak bisa main di berbagai wahana, sementara pendamping istirahat di kafe. Sebelum main, cek ketentuan usia dan tinggi badan di loket, dan siapkan kaus kaki untuk area bermain indoor. Biar aman, sepakati satu titik temu yang gampang diingat, misalnya air mancur di tengah danau, sekitar delapan puluh meter dari sini. Kalau mau istirahat, Zona Teduh ada di sebelah utara. Selamat bermain!', activities = array['Wahana bermain anak', 'Kafe untuk pendamping', 'Titik istirahat keluarga']::text[], tips = array['Sepakati titik temu (misalnya air mancur) bila anggota rombongan terpisah.', 'Cek ketentuan usia dan tinggi badan di loket wahana; bawa kaus kaki untuk area bermain indoor.']::text[], best_times = array['pagi', 'siang', 'sore']::text[], keywords = array['anak', 'bermain', 'playground', 'lollipop', 'keluarga', 'wahana', 'balita']::text[], art = 'playground', status_note = 'Jam operasional wahana perlu dikonfirmasi saat survei.', source_place = 'Google Maps: "Lolipops Playland and Cafe"', sort_order = 10 where id = 'P10';
update public.poi set name = 'Zona Relaksasi / Spot Teduh', short_name = 'Zona Teduh', category_id = 'wellness', zone = 'Kanopi pepohonan di sisi timur danau', location = extensions.st_setsrid(extensions.st_makepoint(107.643112, -6.91593), 4326)::extensions.geography, radius_m = 20, description = 'Area teduh di bawah kanopi pepohonan rindang di sisi timur danau. Tempat ideal untuk berhenti sejenak, mengatur napas, dan melakukan peregangan ringan, sekaligus menjadi checkpoint Wellness Trail.', trigger_response = 'Tawaran audio relaksasi 1–2 menit; menjadi checkpoint Wellness Trail.', qr_code = 'SETARA:POI:P11', data_source = 'google_maps', is_published = true, summary = 'Area duduk teduh untuk relaksasi napas dan peregangan ringan.', narration = 'Selamat datang di Zona Teduh, di bawah kanopi pepohonan sisi timur danau. Yuk, berhenti sebentar bareng aku. Berdiri dengan nyaman atau duduk di bangku terdekat. Tarik napas pelan lewat hidung, empat hitungan. Tahan sebentar. Lalu hembuskan pelan lewat mulut, enam hitungan. Ulangi tiga kali. Sekarang angkat kedua bahu ke arah telinga, tahan, lalu lepaskan. Putar leher pelan ke kiri dan ke kanan. Rasakan udara yang lebih sejuk di bawah pohon ini. Kalau sudah siap, lanjutkan perjalananmu dengan langkah yang lebih ringan.', activities = array['Audio relaksasi 1–2 menit', 'Peregangan ringan', 'Checkpoint Wellness Trail']::text[], tips = array['Lepaskan earphone sejenak dan dengarkan suara di sekitar Anda.', 'Minum air setelah berjalan atau berlari.']::text[], best_times = array['pagi', 'siang', 'sore']::text[], keywords = array['teduh', 'relaksasi', 'istirahat', 'napas', 'peregangan', 'pohon', 'duduk']::text[], art = 'shade', status_note = 'Titik ditentukan dari citra satelit Google Maps; validasi saat survei lapangan.', source_place = 'Google Maps (citra satelit): titik di bawah kanopi pohon, timur danau', sort_order = 11 where id = 'P11';
update public.poi set name = 'Musala & Toilet', short_name = 'Musala & Toilet', category_id = 'fasilitas', zone = 'Fasilitas umum utama, sisi utara taman', location = extensions.st_setsrid(extensions.st_makepoint(107.6421597, -6.9151658), 4326)::extensions.geography, radius_m = 20, description = 'Fasilitas umum utama di sisi utara taman: musala, tempat wudu, dan toilet. Lokasinya dekat Layana Hall dan titik start jogging track, sehingga mudah dijangkau sebelum atau sesudah berolahraga.', trigger_response = 'Info fasilitas dan arah; tampil sebagai hasil cepat pada filter Fasilitas.', qr_code = 'SETARA:POI:P12', data_source = 'google_maps', is_published = true, summary = 'Musala, tempat wudu, dan toilet umum di sisi utara taman.', narration = 'Kamu di area Musala dan Toilet, fasilitas umum utama di sisi utara taman. Di sini ada musala, tempat wudu, dan toilet umum. Menjelang magrib musala biasanya ramai, jadi datang beberapa menit lebih awal, ya. Simpan alas kaki di rak yang tersedia dan bantu jaga kebersihan bareng-bareng. Setelah ini, kamu bisa lanjut ke titik start jogging track di sebelah barat, atau ke danau dan air mancur di selatan. Hatur nuhun sudah ikut menjaga taman!', activities = array['Salat', 'Wudu', 'Toilet umum']::text[], tips = array['Menjelang magrib musala biasanya ramai; datang beberapa menit lebih awal.', 'Jaga kebersihan dan simpan alas kaki di rak yang tersedia.']::text[], best_times = array['pagi', 'siang', 'sore', 'malam']::text[], keywords = array['musala', 'mushola', 'masjid', 'salat', 'sholat', 'toilet', 'wc', 'kamar mandi', 'wudu']::text[], art = 'musala', status_note = null, source_place = 'Google Maps: "Mushalla Kiara Artha Park"', sort_order = 12 where id = 'P12';

