  ('B01', 'Langkah Pertama', 'Kumpulkan stempel pertama Anda.', '{}'::text[], 1, false, 'stamp', 1),
  ('B02', 'Penjelajah Danau', 'Kunjungi 4 spot di sekitar danau.', array['P03', 'P05', 'P10', 'P11']::text[], 4, false, 'stamp', 2),
  ('B03', 'Pencicip Kuliner', 'Kunjungi area kuliner dan kafe.', array['P08', 'P09']::text[], 2, false, 'stamp', 3),
  ('B04', 'Sahabat Sehat', 'Kunjungi 3 spot wellness dan selesaikan satu Wellness Trail.', array['P06', 'P07', 'P11']::text[], 3, true, 'stamp', 4),
  ('B05', 'Penjelajah Sejati', 'Kumpulkan seluruh 12 stempel Kiara Artha Park.', array['P01', 'P02', 'P03', 'P04', 'P05', 'P06', 'P07', 'P08', 'P09', 'P10', 'P11', 'P12']::text[], 12, false, 'stamp', 5),
