-- Interaksi dua arah (migrasi 20261119000000): kuis, misi, Tanya Kia, Tantangan Hari Ini
delete from public.quiz_question;
insert into public.quiz_question (poi_id, trail_id, seq, question, options, answer_index, explanation) values
  ('P01', null, 1, 'Kapan Kiara Artha Park diresmikan?', array['17 Agustus 2019', '24 April 2019', '1 Januari 2020', '17 Agustus 2015']::text[], 0, 'Taman ini diresmikan 17 Agustus 2019, bertepatan dengan HUT ke-74 Republik Indonesia.'),
  ('P01', null, 2, 'Kiara Artha Park berada di antara dua flyover. Flyover apa saja?', array['Pelangi dan Pasupati', 'Pasupati dan Cimindi', 'Cimindi dan Antapani', 'Antapani dan Kiaracondong']::text[], 3, 'Taman ini terletak di antara flyover Antapani dan flyover Kiaracondong, Kelurahan Kebonwaru.'),
  ('P02', null, 1, 'Berapa tiket masuk per orang menurut detikJabar (2024)?', array['Gratis', 'Rp5.000', 'Rp10.000', 'Rp25.000']::text[], 2, 'Tiket tercatat Rp10.000 per orang, hari kerja maupun akhir pekan. Cek lagi di loket karena harga bisa berubah.'),
  ('P02', null, 2, 'Dari gerbang parkir, ke arah mana Pintu Utama?', array['Utara, sekitar 300 m', 'Timur, sekitar 500 m', 'Di seberang Jl. Banten', 'Selatan, sekitar 90 m']::text[], 3, 'Pintu Utama ada sekitar 90 meter ke arah selatan dari gerbang parkir.'),
  ('P03', null, 1, 'Jam berapa pertunjukan air mancur menari biasanya dimulai?', array['16.00', '21.00', '12.00', '18.30']::text[], 3, 'Pertunjukan umumnya mulai pukul 18.30 sampai 20.30, dengan pertunjukan berbeda tiap jam (Orami, 2024).'),
  ('P03', null, 2, 'Apa nama patung jabat tangan di tepi utara danau?', array['Monumen Persahabatan', 'Patung Merdeka', 'Tugu Asia Afrika', 'Friendship Shake Hand']::text[], 3, 'Patung Friendship Shake Hand menggambarkan jabat tangan persahabatan, sejalan dengan semangat Asia Afrika.'),
  ('P04', null, 1, 'Zona bernuansa Asia di sisi barat taman dikenal dengan julukan apa?', array['Kampung Korea', 'Kampung Pecinan', 'Kampung Jepang', 'Little India']::text[], 0, 'Area ini dikenal sebagai Kampung Korea dan sempat membuat Kiara Artha Park dijuluki destinasi ala Korea.'),
  ('P04', null, 2, 'Tulisan khas Korea yang menghiasi area ini disebut apa?', array['Kanji', 'Aksara Sunda', 'Hangeul', 'Hiragana']::text[], 2, 'Hangeul adalah aksara Korea; tulisannya menghiasi ornamen di area ini.'),
  ('P05', null, 1, 'Konferensi Asia Afrika 1955 digelar di gedung apa di Bandung?', array['Gedung Merdeka', 'Gedung Sate', 'Gedung Pakuan', 'Layana Hall']::text[], 0, 'KAA digelar di Gedung Merdeka, Bandung, 18–24 April 1955.'),
  ('P05', null, 2, 'Berapa negara yang hadir di Konferensi Asia Afrika 1955?', array['55 negara', '10 negara', '100 negara', '29 negara']::text[], 3, 'Konferensi Asia Afrika 1955 dihadiri 29 negara.'),
  ('P06', null, 1, 'Kira-kira berapa panjang satu putaran jalur lingkar taman?', array['±5 km', '±200 m', '±2 km', '±750 m']::text[], 3, 'Jalur lingkar Jl. Kiara Artha sekitar 750 meter per putaran.'),
  ('P06', null, 2, 'Acara lari apa yang pernah digelar di Kiara Artha Park?', array['Pocari Run 2025', 'Jakarta Marathon', 'Borobudur Marathon', 'Tour de Bandung']::text[], 0, 'Kiara Artha Park pernah menjadi tuan rumah acara lari Pocari Run 2025.'),
  ('P07', null, 1, 'BOSEH adalah singkatan dari…', array['Bersepeda Olahraga Sehat', 'Bike Of Smart Eco Hub', 'Bandung Ongkos Sepeda Hemat', 'Bike on the Street Everybody Happy']::text[], 3, 'BOSEH = Bike on the Street Everybody Happy, program sepeda sewa Pemkot Bandung.'),
  ('P07', null, 2, 'Berapa tarif resmi BOSEH untuk jam pertama?', array['Rp10.000', 'Rp1.000', 'Rp30.000', 'Rp50.000']::text[], 1, 'Tarif resmi BOSEH tercatat Rp1.000 untuk jam pertama dan Rp2.000 untuk jam berikutnya.'),
  ('P08', null, 1, 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk apa?', array['Tiket Lollipop Playland', 'Akses menonton air mancur menari', 'Sewa sepeda satu jam', 'Parkir gratis']::text[], 1, 'Paketnya disebut sudah termasuk akses menonton air mancur menari (Orami, 2024).'),
  ('P08', null, 2, 'Kafe dekat area ini yang punya rating 4,8 dengan lebih dari seribu ulasan di Google Maps?', array['Ludo Sports Kitchen and Coffee', 'Kopi Kiara', 'Lollipop Cafe', 'Padel Co.']::text[], 0, 'Ludo Sports Kitchen and Coffee punya lebih dari seribu ulasan dengan rating 4,8.'),
  ('P09', null, 1, 'Di negara mana olahraga padel lahir?', array['Meksiko', 'Inggris', 'Spanyol', 'Brasil']::text[], 0, 'Padel lahir di Acapulco, Meksiko, pada 1969.'),
  ('P09', null, 2, 'Apa yang membedakan padel dari tenis?', array['Bola boleh memantul ke dinding', 'Dimainkan tanpa raket', 'Lapangan tanpa net', 'Dimainkan sendirian']::text[], 0, 'Dalam padel, bola boleh memantul ke dinding kaca sebelum dipukul kembali.'),
  ('P10', null, 1, 'Kira-kira berapa jarak Lollipop Playland ke air mancur?', array['±10 m', '±1 km', '±500 m', '±80 m']::text[], 3, 'Area bermain ini sekitar 80 meter dari air mancur, titik temu yang mudah diingat.'),
  ('P10', null, 2, 'Apa yang sebaiknya disepakati sebelum anak-anak bermain?', array['Pulang masing-masing', 'Satu titik temu bila terpisah', 'Tidak perlu apa-apa', 'Bertemu di parkiran besok']::text[], 1, 'Sepakati satu titik temu, misalnya air mancur, bila anggota rombongan terpisah.'),
  ('P11', null, 1, 'Pola napas apa yang Kia ajak latih di Zona Teduh?', array['Tahan napas 1 menit', 'Napas cepat 20 kali', 'Tarik 10, tahan 10', 'Tarik 4 hitungan, hembuskan 6']::text[], 3, 'Menghembuskan napas lebih panjang (6) daripada menarik (4) membantu menenangkan detak jantung.'),
  ('P11', null, 2, 'Mengapa udara di bawah kanopi pohon terasa lebih sejuk?', array['Kanopi menaungi dari terik matahari', 'Ada pendingin udara', 'Karena dekat parkiran', 'Karena tanahnya basah']::text[], 0, 'Kanopi pohon menaungi area di bawahnya sehingga terasa lebih sejuk dibanding area terbuka.'),
  ('P12', null, 1, 'Musala Kiara Artha Park berdekatan dengan gedung apa?', array['Gedung Merdeka', 'Lollipop Playland', 'Layana Hall', 'Padel Co.']::text[], 2, 'Musala ini tercatat di Google Maps berdekatan dengan Layana Hall.'),
  ('P12', null, 2, 'Selain di sini, di mana lagi toilet umum tersedia?', array['Tidak ada lagi', 'Sekitar area parkir sisi barat laut', 'Di tengah danau', 'Di Taman Asia Afrika']::text[], 1, 'Toilet umum lain tersedia di sekitar area parkir sisi barat laut taman.'),
  (null, 'T01', 1, 'Pola napas di Rute Santai: tarik berapa hitungan, hembuskan berapa?', array['Tarik 10, hembuskan 10', 'Tarik 2, hembuskan 2', 'Tarik 6, hembuskan 4', 'Tarik 4, hembuskan 6']::text[], 3, 'Hembusan yang lebih panjang (6) dari tarikan (4) membantu tubuh lebih rileks.'),
  (null, 'T01', 2, 'Setelah selesai berjalan, sebaiknya kamu…', array['Langsung lari sprint', 'Tidak perlu apa-apa', 'Pendinginan dan minum air', 'Duduk tanpa bergerak lama']::text[], 2, 'Pendinginan meregangkan otot, dan minum air mengganti cairan yang keluar.'),
  (null, 'T02', 1, 'Saat jogging dengan ritme nyaman, kamu seharusnya…', array['Menahan napas', 'Masih bisa ngobrol dengan nyaman', 'Berhenti tiap 10 meter', 'Terengah-engah tak bisa bicara']::text[], 1, 'Kalau masih bisa ngobrol, intensitas jogging-mu pas.'),
  (null, 'T02', 2, 'Posisi lengan yang dianjurkan saat berlari?', array['Menekuk sekitar 90 derajat', 'Dimasukkan ke saku', 'Lurus kaku ke bawah', 'Diangkat di atas kepala']::text[], 0, 'Lengan menekuk 90 derajat membantu ayunan yang efisien.');
delete from public.mission;
insert into public.mission (poi_id, type, title, prompt, done_label, seconds, cues) values
  ('P01', 'photo', 'Foto pertama di Jurnal', 'Foto gerbang barat dari tempatmu berdiri. Ini jadi halaman pertama Jurnal Kunjunganmu!', null, null, '[]'::jsonb),
  ('P02', 'confirm', 'Ingat tempat parkirmu', 'Catat blok atau patokan tempat kendaraanmu diparkir supaya mudah ditemukan saat pulang.', 'Sudah kucatat!', null, '[]'::jsonb),
  ('P03', 'confirm', 'Cari patung jabat tangan', 'Lihat ke tepi utara danau dan temukan patung Friendship Shake Hand, dua tangan yang berjabat.', 'Ketemu!', null, '[]'::jsonb),
  ('P04', 'confirm', 'Amati dari luar', 'Google Maps mencatat area ini tutup. Dari luar, cari satu ornamen bernuansa Korea, misalnya atap atau tulisan Hangeul.', 'Sudah kulihat!', null, '[]'::jsonb),
  ('P05', 'photo', 'Foto ikonik Asia Afrika', 'Menghadaplah ke utara dan ambil foto berlatar danau dan air mancur.', null, null, '[]'::jsonb),
  ('P06', 'timer', 'Pemanasan 60 detik', 'Ikuti aba-aba Kia sampai waktunya habis. Gerakkan badan pelan-pelan saja.', null, 60, '[{"at":0,"text":"Putar pergelangan kaki kanan."},{"at":15,"text":"Ganti, putar pergelangan kaki kiri."},{"at":30,"text":"Ayunkan kedua lengan ke depan dan ke belakang."},{"at":45,"text":"Sekarang jalan di tempat."}]'::jsonb),
  ('P07', 'confirm', 'Intip selter BOSEH', 'Lihat ke selter: ada sepeda yang siap disewa sekarang? Perhatikan juga papan tarifnya.', 'Sudah kuintip!', null, '[]'::jsonb),
  ('P08', 'photo', 'Foto menu favorit', 'Foto makanan atau minuman yang paling menggoda di area kuliner.', null, null, '[]'::jsonb),
  ('P09', 'confirm', 'Tonton satu reli', 'Tonton pemain padel sampai satu reli selesai. Perhatikan bola yang memantul ke dinding kaca!', 'Sudah kutonton!', null, '[]'::jsonb),
  ('P10', 'confirm', 'Sepakati titik temu', 'Ajak rombonganmu menyepakati satu titik temu kalau terpisah, misalnya air mancur.', 'Sudah sepakat!', null, '[]'::jsonb),
  ('P11', 'timer', 'Napas 4-6 selama 60 detik', 'Tarik napas 4 hitungan, hembuskan 6 hitungan. Ikuti aba-aba Kia.', null, 60, '[{"at":0,"text":"Tarik napas."},{"at":4,"text":"Hembuskan perlahan."},{"at":10,"text":"Tarik napas."},{"at":14,"text":"Hembuskan perlahan."},{"at":20,"text":"Tarik napas."},{"at":24,"text":"Hembuskan perlahan."},{"at":30,"text":"Tarik napas."},{"at":34,"text":"Hembuskan perlahan."},{"at":40,"text":"Tarik napas."},{"at":44,"text":"Hembuskan perlahan."},{"at":50,"text":"Tarik napas."},{"at":54,"text":"Hembuskan perlahan."}]'::jsonb),
  ('P12', 'confirm', 'Jaga kebersihan', 'Simpan alas kaki di rak dan buang satu sampah yang kamu lihat ke tempatnya.', 'Sudah!', null, '[]'::jsonb);
delete from public.kia_faq;
insert into public.kia_faq (id, patterns, answer, poi_id, sort_order) values
  ('tiket', array['tiket', 'harga masuk', 'bayar masuk', 'htm', 'biaya masuk']::text[], 'Tiket masuk tercatat Rp10.000 per orang, hari kerja maupun akhir pekan (detikJabar, 2024). Cek lagi di loket, ya, harga bisa berubah.', 'P02', 1),
  ('alamat', array['alamat', 'lokasi taman', 'letak taman', 'taman ini di mana']::text[], 'Kiara Artha Park ada di Jl. Banten, Kebonwaru, Kecamatan Batununggal, Kota Bandung, di antara flyover Antapani dan flyover Kiaracondong.', 'P01', 2),
  ('kontak', array['kontak', 'telepon', 'nomor hp', 'nomor telepon', 'instagram', 'ig', 'pengelola']::text[], 'Info resmi taman: Instagram @kiaraarthapark dan telepon 0822-1583-8889.', null, 3),
  ('angkutan', array['angkot', 'bus', 'transportasi', 'naik apa', 'trans metro', 'kendaraan umum', 'halte']::text[], 'Bus Trans Metro Bandung Koridor 5 berhenti di halte Kiara Artha. Dari selter BOSEH di sisi barat, kamu juga bisa lanjut bersepeda.', 'P07', 4),
  ('sewa', array['sewa sepeda', 'skuter', 'otoped', 'harga sepeda', 'tarif sepeda', 'boseh']::text[], 'BOSEH (sepeda Pemkot Bandung) mulai Rp1.000 untuk jam pertama. Sewa sepeda dan skuter listrik di dalam taman sekitar Rp30.000 di hari kerja dan Rp40.000 di akhir pekan (detikJabar, 2024).', 'P07', 5),
  ('paket', array['paket', 'food court', 'makan malam', 'paket makan']::text[], 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk akses menonton air mancur menari (Orami, 2024). Konfirmasi lagi di lokasi, ya.', 'P08', 6),
  ('padel', array['booking padel', 'sewa lapangan', 'reservasi', 'pesan lapangan', 'main padel']::text[], 'Lapangan padel dipesan langsung ke pengelola Padel Co. SETARA belum menyediakan reservasi.', 'P09', 7),
  ('anak', array['usia anak', 'tinggi badan', 'kaus kaki', 'wahana anak']::text[], 'Cek ketentuan usia dan tinggi badan di loket Lollipop Playland, dan bawa kaus kaki untuk area bermain indoor.', 'P10', 8),
  ('kia', array['kamu siapa', 'siapa kamu', 'kia siapa', 'siapa kia', 'kenalan']::text[], 'Aku Kia, tunas pohon kiara! Aku menemanimu menjelajah, membacakan cerita spot, dan memberi kuis serta misi. Makin banyak bintang yang kamu kumpulkan, makin tinggi aku tumbuh.', null, 9),
  ('kiara', array['pohon kiara', 'asal nama', 'arti kiara', 'nama kiara']::text[], 'Kiara adalah pohon sejenis beringin (Ficus). Nama Kiaracondong konon berasal dari pohon kiara yang tumbuh condong.', null, 10),
  ('privasi', array['privasi', 'data saya', 'lokasi saya dikirim', 'aman nggak']::text[], 'Lokasimu hanya diproses di ponsel dan tidak pernah dikirim ke server. Yang terkirim tanpa identitas hanya rating, laporan, hasil kuis, dan pertanyaan yang belum bisa kujawab.', null, 11);
